# nerva for macOS: brew install nervalog/tap/nerva
#
# Generated by `zig build mac-release` in NervaLog/nerva from packaging/homebrew/nerva.rb, which
# holds placeholders for the version, the archive's URL and its SHA-256. The tap's
# Formula/nerva.rb is that output. It installs the prebuilt universal binary (arm64 and x86_64),
# signed with Developer ID, from the GitHub release; it does not build from source. Nothing here
# needs sudo: brew writes only under its own prefix.
class Nerva < Formula
  desc "Research database: derived state declared and maintained from one replicated log"
  homepage "https://github.com/NervaLog/nerva"
  url "@URL@"
  version "@VERSION@"
  sha256 "@SHA256@"
  license "Apache-2.0"

  depends_on :macos

  def install
    bin.install "nerva"
  end

  test do
    assert_match "version #{version}", shell_output("#{bin}/nerva version")
  end
end
